    @Test
    fun `REQ-SEND-002 REQ-SEND-003 REQ-SEND-004 a valid send persists a queued message, appends it to the outbox and wakes`() = runTest {
        val dispatcher = StandardTestDispatcher(testScheduler)
        val identity = IdentityRepositoryImpl(InMemoryValue("identity", "Alice"), dispatcher)
        val values = StoreValues()
        val messages = values.repository(dispatcher)
        val controller = FakeSyncController()
        val clock = Clock.fixed(Instant.parse("2026-10-15T13:04:05.120Z"), ZoneOffset.UTC)
        var n = 0
        val send = SendMessageUseCase(identity, messages, controller, clock) { "0F8FAD5B-D9CB-469F-A165-7086772895${n++}E" }

        val first = (send("Bob", "  hello  ") as SendResult.Sent).message
        assertEquals("0f8fad5b-d9cb-469f-a165-70867728950e", first.id)
        assertEquals("text", first.kind)
        assertEquals("Alice", first.from)
        assertEquals("Bob", first.to)
        assertEquals("  hello  ", first.body)
        assertEquals("2026-10-15T13:04:05.120Z", first.createdAt)
        assertEquals(MessageStatus.QUEUED, first.status)
        assertNull(first.seq)
        assertNull(first.receivedAt)
        assertNull(first.errorCode)

        // Same clock millisecond: createdAt is the previous maximum + 1 ms.
        val second = (send("Bob", "again") as SendResult.Sent).message
        assertEquals("2026-10-15T13:04:05.121Z", second.createdAt)

        assertEquals(listOf(first.id, second.id), messages.outbox.value)
        assertEquals(listOf("write messages", "write outbox", "write messages", "write outbox"), values.log)
        assertEquals(2, controller.wakes)
    }

